import SwiftUI
import AtiCleanerCore
struct TrashView:View{@State private var includeExternal=false;@State private var items:[CleanableItem]=[];var body:some View{VStack(alignment:.leading,spacing:18){PageHeader(icon:"trash",title:"Çöp Kutusu",subtitle:"Mac ve isteğe bağlı harici disk çöp kutularını inceleyin.",tint:Theme.trash,actionTitle:"Tara",action:{items=TrashScanner.items(includeExternal:includeExternal)});Toggle("Harici disklerin çöp kutularını da tara",isOn:$includeExternal).toggleStyle(.switch);if items.isEmpty{VStack(spacing:18){ReadyRing(icon:"trash",title:"Taramaya Hazır",detail:includeExternal ? "Mac + harici diskler":"Yalnız Mac",tint:Theme.trash);HStack{InfoTile(icon:"internaldrive.fill",title:"Mac Çöp Kutusu",subtitle:"Kullanıcı çöp kutusu",tint:Theme.trash);InfoTile(icon:"externaldrive.fill",title:"Harici Diskler",subtitle:includeExternal ? "Taramaya dahil":"İsteğe bağlı",tint:Theme.trash);InfoTile(icon:"eye.fill",title:"Önce İncele",subtitle:"Silmeden önce listeyi kontrol edin",tint:Theme.trash)}.frame(maxWidth:820)}.frame(maxWidth:.infinity)}else{List(items){i in HStack{Text(i.name);Spacer();Text(i.size.formattedBytes).foregroundStyle(.secondary)}}}}.padding(24)}}
